import { Mesh, PlaneGeometry, Object3D, Vector3, Vector2 } from 'three/webgpu';
import {
    MeshBasicNodeMaterial,
    texture,
    uv,
    vec2
} from 'three/tsl';
import { gsap } from 'gsap';
import { NodeConfig, NodeContext } from '@/primitives';

export default function createNode(config: NodeConfig, ctx: NodeContext): Object3D {
    // -----------------------------------------------------------------
    // Load texture
    // -----------------------------------------------------------------
    const imageUrl = (config.assets && config.assets.imageUrl) || (config as any).imageUrl;
    const tex = ctx.textureLoader.load(imageUrl);

    // -----------------------------------------------------------------
    // Atlas region handling
    // -----------------------------------------------------------------
    const sourceRect = (config.atlasRegion && config.atlasRegion.sourceRect) || [0, 0, 512, 320];
    const [rx, ry, rw, rh] = sourceRect as [number, number, number, number];

    // Default UV scale/offset (will be updated once texture image is available)
    const uvScale = new Vector2(1, 1);
    const uvOffset = new Vector2(0, 0);

    const updateUVTransform = () => {
        if (tex.image) {
            const texW = (tex.image as HTMLImageElement).width;
            const texH = (tex.image as HTMLImageElement).height;
            uvScale.set(rw / texW, rh / texH);
            uvOffset.set(rx / texW, ry / texH);
        }
    };

    // Attempt immediate update (in many cases texture image is already loaded)
    updateUVTransform();

    // Fallback: ensure UV transform updates when the image finally loads
    if (!tex.image) {
        // three's texture does not emit events; we poll once the image becomes available
        const check = () => {
            if (tex.image) {
                updateUVTransform();
                return;
            }
            requestAnimationFrame(check);
        };
        check();
    }

    // -----------------------------------------------------------------
    // Build material with UV transform node
    // -----------------------------------------------------------------
    const uvNodeTransformed = uv()
        .mul(vec2(() => uvScale.x, () => uvScale.y))
        .add(vec2(() => uvOffset.x, () => uvOffset.y));

    const mapNode = texture(tex, uvNodeTransformed);

    const material = new MeshBasicNodeMaterial({
        map: mapNode,
        transparent: true,
        depthWrite: false
    });

    // -----------------------------------------------------------------
    // Geometry – sized to the atlas region's aspect ratio
    // -----------------------------------------------------------------
    const aspect = rw / rh;
    const geometry = new PlaneGeometry(aspect, 1);

    // -----------------------------------------------------------------
    // Mesh setup
    // -----------------------------------------------------------------
    const mesh = new Mesh(geometry, material);
    mesh.frustumCulled = false; // sprites often stay visible beyond frustum

    // Position / rotation / scale from config (fallback to spec defaults)
    const pos = (config.position as [number, number, number]) ?? [-3.2, -0.3, 0];
    const rot = (config.rotation as [number, number, number]) ?? [0, 0, 0];
    const scl = (config.scale as [number, number, number]) ?? [1, 1, 1];

    mesh.position.set(pos[0], pos[1], pos[2]);
    mesh.rotation.set(rot[0], rot[1], rot[2]);
    mesh.scale.set(scl[0], scl[1], scl[2]);

    // -----------------------------------------------------------------
    // Billboard behavior – face the active camera each render
    // -----------------------------------------------------------------
    mesh.onBeforeRender = (_renderer, _scene, camera) => {
        mesh.quaternion.copy(camera.quaternion);
    };

    // -----------------------------------------------------------------
    // UserData for handlers and cleanup
    // -----------------------------------------------------------------
    mesh.userData.handlers = {};

    mesh.userData.cleanup = () => {
        // Remove render hook
        mesh.onBeforeRender = null;

        // Dispose three.js resources
        geometry.dispose();
        material.dispose();
        tex.dispose();

        // Kill any GSAP timelines that might have been created (none in this node)
        gsap.globalTimeline.clear();
    };

    // -----------------------------------------------------------------
    // Return the prepared Object3D
    // -----------------------------------------------------------------
    return mesh;
}
